def compress_ranges(lst):
    if not lst:
        return []
    res = []
    start = prev = lst[0]
    for x in lst[1:]:
        if x == prev + 1:
            prev = x
        else:
            res.append([start, prev])
            start = prev = x
    res.append([start, prev])
    return res

def interleave_lists(a, b):
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
    return result

def minutes_to_time_str(minutes):
    m = minutes % 1440
    return f'{m//60:02d}:{m%60:02d}'

def is_valid_simple_email(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local or local.startswith('.') or local.endswith('.') or '..' in local:
        return False
    if not all(c.isalnum() or c in '._+-' for c in local):
        return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not label or label.startswith('-') or label.endswith('-'):
            return False
        if not all(c.isalnum() or c == '-' for c in label):
            return False
    tld = labels[-1]
    return tld.isalpha() and len(tld) >= 2

def merge_dict_lists_unique(d1, d2):
    keys = set(d1) | set(d2)
    res = {}
    for k in keys:
        vals = set(d1.get(k, [])) | set(d2.get(k, []))
        res[k] = sorted(vals)
    return res

def primes_up_to(n):
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i in range(n + 1) if sieve[i]]

def quarter_of_month(month_index):
    normalized = (month_index - 1) % 12 + 1
    return (normalized - 1)//3 + 1

def remove_vowels_keep_positions(s):
    vowels = set("aeiouAEIOU")
    return "".join('_' if c in vowels else c for c in s)

def acronym_word_start_indices(s):
    if not s:
        return []
    indices = [0]
    for i, c in enumerate(s):
        if c == ' ' and i + 1 < len(s):
            indices.append(i + 1)
    return indices

def reverse_digits_in_string(s):
    digits = [ch for ch in s if ch.isdigit()][::-1]
    out = []
    idx = 0
    for ch in s:
        if ch.isdigit():
            out.append(digits[idx])
            idx += 1
        else:
            out.append(ch)
    return ''.join(out)

def count_substring_occurrences_nonoverlapping(s, sub):
    if not sub:
        return 0
    count = 0
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        count += 1
        start = idx + len(sub)
    return count

def pairwise_differences(lst):
    if len(lst) < 2:
        return []
    return [lst[i+1] - lst[i] for i in range(len(lst) - 1)]

def merged_busy_minutes(intervals):
    if not intervals:
        return 0
    ivs = sorted(intervals)
    total = 0
    cur_s, cur_e = ivs[0]
    for s, e in ivs[1:]:
        if s > cur_e:
            total += cur_e - cur_s
            cur_s, cur_e = s, e
        else:
            cur_e = max(cur_e, e)
    total += cur_e - cur_s
    return total

def distinct_items_per_group(pairs):
    groups = {}
    for g, item in pairs:
        groups.setdefault(g, set()).add(item)
    return {g: len(s) for g, s in groups.items()}

import math
def is_sum_of_two_squares(n):
    a = 0
    while a * a <= n:
        b2 = n - a * a
        b = math.isqrt(b2)
        if b * b == b2:
            return True
        a += 1
    return False

def is_valid_mac_address_dashed(s):
    groups = s.split('-')
    if len(groups) != 6:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(len(g) == 2 and all(c in hexdigits for c in g) for g in groups)

def add_minutes_with_day_offset(time_str, minutes):
    h, m = time_str.split(':')
    total = int(h)*60 + int(m) + minutes
    day_offset = total // 1440
    rem = total % 1440
    return (day_offset, f'{rem//60:02d}:{rem%60:02d}')

def dedent_lines(text, n):
    out = []
    for line in text.split("\n"):
        count = 0
        while count < n and count < len(line) and line[count] == " ":
            count += 1
        out.append(line[count:])
    return "\n".join(out)

def is_valid_variable_declaration(s):
    parts = s.split(' ')
    if len(parts) != 2:
        return False
    typ, name = parts
    if typ not in {'int', 'float', 'str', 'bool'}:
        return False
    if not name or not (name[0].isalpha() or name[0] == '_'):
        return False
    return all(c.isalnum() or c == '_' for c in name)

def subtract_business_days(start_day_num, n, weekend_days):
    d = start_day_num
    count = 0
    while count < n:
        d -= 1
        if d % 7 not in weekend_days:
            count += 1
    return d

def top_k_keys_by_value(d, k):
    items = sorted(d.items(), key=lambda kv: (-kv[1], kv[0]))
    return [kv[0] for kv in items[:k]]
